import math


def reserve(remaining_seconds, used_attempts, max_attempts):
    if isinstance(remaining_seconds, bool) or not isinstance(remaining_seconds, (int, float)):
        raise ValueError("remaining_seconds must be an int or float")
    if isinstance(remaining_seconds, float) and not math.isfinite(remaining_seconds):
        raise ValueError("remaining_seconds must be finite")
    if isinstance(used_attempts, bool) or not isinstance(used_attempts, int) or used_attempts < 0:
        raise ValueError("used_attempts must be a nonnegative integer")
    if isinstance(max_attempts, bool) or not isinstance(max_attempts, int) or max_attempts < 1:
        raise ValueError("max_attempts must be a positive integer")
    if used_attempts > max_attempts:
        raise ValueError("used_attempts cannot exceed max_attempts")

    if remaining_seconds > 0 and used_attempts < max_attempts:
        return True, used_attempts + 1
    return False, used_attempts
